text:
#calsidebar_splitter,
#today-splitter {
  /* splitter grip area */
  inline-size: 5px;
  border-width: 0;
  min-inline-size: 0;
  margin-block-start: 0;
  /* because of the negative margin needed to make the splitter visible */
  position: relative;
  z-index: 10;
  transition: border-width 0.3s ease-in;
}

#calsidebar_splitter[state="collapsed"] {
  border-inline-start: 1px solid transparent;
}

#calsidebar_splitter[state="collapsed"]:hover {
  border-inline-start: 4px solid var(--selected-item-color);
}

@media not (-moz-platform: macos) {
  #calsidebar_splitter,
  #today-splitter {
    min-inline-size: 0;
    background-color: transparent;
  }

  #today-splitter {
    border-inline-end: 1px solid var(--sidebar-border);
    margin-inline-start: -5px;
    position: relative;
  }

  :root[lwtheme] #today-splitter.calendar-sidebar-splitter {
    background-image: none;
  }
}
